CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY NOT NULL,slot INTEGER NOT NULL,attempts INTEGER NOT NULL CHECK(attempts>=1)); CREATE TABLE IF NOT EXISTS order_requests (request_id TEXT PRIMARY KEY NOT NULL,fingerprint TEXT NOT NULL,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id) ON DELETE CASCADE); CREATE TABLE IF NOT EXISTS product_photos (id TEXT PRIMARY KEY NOT NULL,product_id TEXT NOT NULL UNIQUE REFERENCES products(id) ON DELETE CASCADE,mime TEXT NOT NULL CHECK(mime IN ('image/webp','image/jpeg','image/png')),bytes BLOB NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 20 AND 180000)); CREATE TABLE IF NOT EXISTS stock_reservations (order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('product','option')),item_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(order_id,kind,item_id));
